mapper.select:
select  IFNULL(SUM(integral),0)
from integral_log
where 1 = 1

    and create_time >= #{dayStart} and create_time < #{dayEnd}


    and user_id = #{memberId}

select ua.*,su.avatar as userAvatar,su.realname as userName,su.phone as userPhone from integral_log ua left join sys_user su on su.id = ua.user_id where 1 = 1
and (su.realname like CONCAT('%',#{paramCondition.keyword},'%') or su.phone like CONCAT('%',#{paramCondition.keyword},'%'))
AND ua.user_id = #{paramCondition.userId}
AND ua.integral_resource = #{paramCondition.integralResource}
order by ua.create_time desc
